  'site.why.r1b': 'RERA-registered, ISO-certified with full professional indemnity on every project.',
  'site.why.r2t': 'Transparent Pricing',
  'site.why.r2b': 'Line-item BOQs and milestone-based payments — you approve every rupee before it is spent.',
