  'site.calculators.readyMix.method': 'Ready-mix concrete is bought by volume, so this is the geometric volume of the pour plus an allowance for spillage, over-excavation and pump losses. The 5–10% allowance range is the one published Indian construction references give; it is offered as a choice rather than applied silently. The concrete grade is the supplier\'s mix design and does not change the volume you need, so no mix ratio is assumed here.',
  'site.calculators.vastu.direction.n': 'North',
