  'site.calculators.vastu.title': 'Vastu Calculator',
  'site.calculators.vastu.intro': 'Choose the direction each part of your home faces and see how the placements score against traditional Vastu direction principles.',
  'site.calculators.vastu.optional': '(optional)',
  'site.calculators.vastu.selectDirection': 'Select a direction',
  'site.calculators.vastu.notApplicable': 'Not applicable',
  'site.calculators.vastu.missing': 'Select a direction for: {list}.',
  'site.calculators.vastu.headline': 'Vastu compliance',
  'site.calculators.vastu.headlineSub': 'Based on the {count} placement you selected',
  'site.calculators.vastu.headlineSubPlural': 'Based on the {count} placements you selected',
  'site.calculators.vastu.analysis': 'Placement analysis',
  'site.calculators.vastu.favourableCount': 'Favourable ({count})',
  'site.calculators.vastu.attentionCount': 'Needs attention ({count})',
  'site.calculators.vastu.method': 'Each placement carries a traditional preference score from 3 (least favoured) to 10 (most favoured) for each of the eight directions. The compliance figure is the average of the placements you selected, expressed out of 100 — so the scale runs from 30% to 100%, because even the least favoured direction scores 3. Above 70% is treated as good and above 90% as excellent. Parts of the house you leave unselected are not scored at all, rather than counted as zero.',
  'site.calculators.vastu.noteLabel': 'Please note:',
  'site.calculators.vastu.note': 'this is traditional Vastu guidance offered for information only. It is not a scientific assessment and carries no guarantee, and it is not a substitute for professional architectural, structural, engineering or qualified Vastu consultation. Always confirm any building decision with the relevant professional.',
  'site.calculators.plan.title': 'Upload Your Plan',
  'site.calculators.plan.intro': 'Have a floor plan but not sure which way each room faces? Mark the centre and the rooms on your own plan and the directions are worked out for you, then scored by the same rules as the calculator above.',
  'site.calculators.plan.step1': '1. Floor plan',
  'site.calculators.plan.step1Hint': '(JPG or PNG, up to 10 MB)',
  'site.calculators.plan.step2': '2. Which direction does the',
  'site.calculators.plan.step2Top': 'top',
  'site.calculators.plan.step2Rest': 'of this plan face?',
  'site.calculators.plan.step2Hint': 'Starts at North, because most plans are drawn north-up. If your plan\'s north arrow points elsewhere, change this — every room direction depends on it.',
  'site.calculators.plan.step3': '3. Centre point (Brahmasthan)',
  'site.calculators.plan.centreClick': 'Click the centre on the plan',
  'site.calculators.plan.centreMove': 'Move the centre point',
  'site.calculators.plan.centreSet': 'Set the centre point',
  'site.calculators.plan.step3Hint': 'Starts at the middle of the plan. Move it if the built area sits off-centre.',
