  'site.calculators.plan.blockerMark': 'mark {list}',
  'site.calculators.plan.errType': 'Upload the plan as a JPG or PNG image. PDF plans are not supported here — export the page as an image first.',
  'site.calculators.plan.errSize': 'That file is larger than 10 MB. Use a smaller export of the same plan.',
  'site.calculators.plan.headline': 'Vastu compliance — from your plan',
  'site.calculators.plan.headlineSub': 'Based on {count} room marked on {name}',
  'site.calculators.plan.headlineSubPlural': 'Based on {count} rooms marked on {name}',
  'site.calculators.plan.roomByRoom': 'Room-by-room analysis',
  'site.calculators.plan.recommendations': 'Recommendations ({count})',
  'site.calculators.plan.method': 'Each room\'s direction is the bearing from the centre point you set to the marker you placed, rotated by the orientation you confirmed — so it comes from the plan itself rather than from an assumption about which way it was drawn. The scoring is the calculator\'s own: a traditional preference score from 3 to 10 per direction, averaged over the rooms you marked and expressed out of 100, which is why the scale runs 30% to 100%. Rooms you do not mark are not scored. Nothing is uploaded or stored — the plan stays in your browser.',
  'site.calculators.plan.note': 'this is traditional Vastu guidance offered for information only. It is not a scientific assessment and carries no guarantee, and it is not a substitute for professional architectural, structural, engineering or qualified Vastu consultation.',
