  'site.calculators.propertyTds.errDate': 'Enter a valid date.',
  'site.calculators.propertyTds.previousTitle': 'Previous tax framework',
  'site.calculators.propertyTds.previousBody': 'This transaction falls under the previous tax framework (deduction date {date}). The current calculator uses the Income-tax Act, 2025 for transactions from 1 April 2026 onward, so no amount is calculated here. Verify the historical Section 194-IA rules for this transaction.',
  'site.calculators.propertyTds.previousLink': 'Historical Section 194-IA guidance — Income Tax Department',
  'site.calculators.propertyTds.applicableTitle': 'TDS appears applicable based on the entered values',
  'site.calculators.propertyTds.applicableBody': 'The higher of the sale price and the stamp duty value ({base}) is above {threshold}, so TDS under section 393(1) [Table: Sl. No. 3(i)] appears applicable on the entire amount.',
  'site.calculators.propertyTds.notApplicableTitle': 'TDS does not appear applicable based on the entered values.',
  'site.calculators.propertyTds.notApplicableBody': 'Both the sale price and the stamp duty value are below {threshold} (higher value: {base}).',
  'site.calculators.propertyTds.boundaryTitle': '₹50 lakh boundary requires verification',
  'site.calculators.propertyTds.boundaryBody': 'The current official text contains conflicting threshold wording for an amount exactly equal to ₹50 lakh. Please verify the transaction with the Income Tax Department or a qualified tax professional before deducting TDS.',
  'site.calculators.propertyTds.boundaryDetail': 'Section 393(1)(a) refers to amounts that exceed the threshold, while Note 3 to the Table refers to amounts equal to or greater than fifty lakh rupees. No TDS amount is shown for this case.',
  'site.calculators.propertyTds.noPanTitle': 'Seller PAN not available — higher rate',
  'site.calculators.propertyTds.noPanBody': 'Under current official tax rules (section 397(2) of the Income-tax Act, 2025), when the seller does not furnish a valid PAN, tax is deducted at the higher of the rate in the Act, the rate in force, or 20%. This calculator therefore uses 20%. An invalid PAN is treated as not furnished.',
  'site.calculators.propertyTds.linkSection397': 'Section 397 — Income Tax Department',
  'site.calculators.propertyTds.headline': 'Estimated TDS @ {rate}%',
  'site.calculators.propertyTds.headlineSub': 'Net amount payable to seller after TDS: {net}',
  'site.calculators.propertyTds.sellerPaymentTitle': 'Net Seller Payment',
  'site.calculators.propertyTds.grossConsideration': 'Gross sale consideration',
  'site.calculators.propertyTds.lessTds': 'Less: TDS @ {rate}%',
  'site.calculators.propertyTds.netToSeller': 'Net Amount Payable to Seller',
  'site.calculators.propertyTds.tdsExceedsPrice': 'The calculated TDS is higher than the sale price entered. Verify the values with a tax professional.',
  'site.calculators.propertyTds.sdvBaseNote': 'TDS is calculated on the stamp duty value because it is higher than the sale price; the seller is still paid from the sale price.',
  'site.calculators.propertyTds.summaryTitle': 'Transaction Summary',
  'site.calculators.propertyTds.tdsBase': 'TDS Calculation Base',
  'site.calculators.propertyTds.baseSource.salePrice': 'sale price',
  'site.calculators.propertyTds.baseSource.stampDutyValue': 'stamp duty value',
  'site.calculators.propertyTds.baseSource.equal': 'both equal',
  'site.calculators.propertyTds.tdsRate': 'TDS Rate',
  'site.calculators.propertyTds.tdsAmount': 'TDS Amount',
  'site.calculators.propertyTds.tdsDeducted': 'TDS Deducted',
  'site.calculators.propertyTds.notDetermined': 'Not determined — verify',
  'site.calculators.propertyTds.depositTitle': 'TDS Payment / Deposit',
  'site.calculators.propertyTds.deductionDate': 'TDS deduction date',
  'site.calculators.propertyTds.deductionFrom.payment': 'payment date',
  'site.calculators.propertyTds.deductionFrom.credit': 'credit date (earlier)',
  'site.calculators.propertyTds.deductionFrom.both': 'payment and credit',
  'site.calculators.propertyTds.paymentDeadline': 'Pay with Form 141 by',
  'site.calculators.propertyTds.certificateDeadline': 'Issue Form 132 to seller by',
  'site.calculators.propertyTds.tan': 'TAN',
  'site.calculators.propertyTds.tanValue': 'Not required',
  'site.calculators.propertyTds.deadlineNote': 'TDS is deducted when the amount is credited to the seller or paid, whichever is earlier. It must be paid to the Central Government within thirty days from the end of the month of deduction, with the challan-cum-statement in Form 141 (Rules 218(3) and 219(5), Income-tax Rules, 2026). Form 132 is due within 15 days from the Form 141 due date. If you pay in instalments, TDS applies to each instalment on its own date.',
  'site.calculators.propertyTds.tanVsPan': 'TAN is not required for this property-buyer transaction (section 397(1)(c)(i)); Form 141 is filed using the buyer\'s PAN. PAN of the seller is a separate requirement — see the PAN rule above.',
  'site.calculators.propertyTds.form141Title': 'Form 141',
  'site.calculators.propertyTds.form141Body': 'Form 141 is the current challan-cum-statement for paying and reporting this property TDS (it replaced Form 26QB). The buyer files it online on the Income Tax e-Filing portal using PAN login (e-File → e-Pay Tax → Income Tax Act 2025 → New Payment → Form 141). This calculator does not create or submit Form 141.',
  'site.calculators.propertyTds.form141Link': 'Form 141 FAQs — Income Tax e-Filing',
  'site.calculators.propertyTds.form132Title': 'Form 132',
  'site.calculators.propertyTds.form132Body': 'Form 132 is the current TDS certificate the buyer gives the seller (it replaced Form 16B). It is downloaded from TRACES after Form 141 is filed and processed, and is the seller\'s proof of the tax deducted and deposited, used to claim TDS credit in their income-tax return. This calculator does not generate Form 132.',
  'site.calculators.propertyTds.form132Link': 'Form 132 FAQs — Income Tax Department',
  'site.calculators.propertyTds.scope': 'Scope: payments to a resident seller for immovable property (land other than agricultural land, a building or part of a building) under section 393(1) [Table: Sl. No. 3(i)]. Not covered: non-resident sellers, agricultural land, compulsory acquisition. Stamp duty and registration charges are not calculated here — use the Stamp Duty & Registration calculator.',
  'site.calculators.propertyTds.method': 'TDS base = higher of the sale price and the stamp duty value. Below ₹50 lakh: TDS does not appear applicable; exactly ₹50 lakh: needs verification; above ₹50 lakh: TDS = base × 1% (20% if the seller\'s PAN is not furnished). Net payable to seller = sale price − TDS.',
  'site.calculators.propertyTds.disclaimer': 'This calculator provides an estimate based on the information you enter and the currently verified property TDS rules (section 393(1) of the Income-tax Act, 2025, formerly Section 194-IA). It does not constitute tax, legal or financial advice.',
  'site.calculators.propertyTds.rulesChange': 'Tax rules can change. Verify the transaction with the Income Tax Department or a qualified tax professional before making a payment.',
  'site.calculators.propertyTds.linkSection393': 'Section 393 — Income-tax Act, 2025',
