  'site.calculators.constructionFinance.firstGapTag': 'First gap',
  'site.calculators.constructionFinance.assumptionStart': 'Planning assumption: own funds, other funds and the whole construction loan are available from the start; stages are paid in order. Remaining funds = funding available − cumulative stage cost.',
  'site.calculators.constructionFinance.assumptionProgressive': 'Planning assumption: own funds and other funds are available from the start; the loan becomes available by the cumulative % you entered for each stage. Remaining funds = funding available − cumulative stage cost.',
  'site.calculators.constructionFinance.method': 'Contingency = budget × contingency% ÷ 100; Planning Budget = budget + contingency. Total funding = own funds + loan + other funds. Potential funding gap = max(planning budget − funding, 0); surplus = max(funding − planning budget, 0); coverage = funding ÷ planning budget × 100. Stage cost = planning budget × stage% ÷ 100, or the amount you entered.',
  'site.calculators.constructionFinance.disclosure': 'This calculator is a construction cash-flow planning tool based on the amounts and stage allocations you enter. Actual construction costs, payment timing, loan disbursement and project duration can vary.',
