  'site.calculators.contractorQuote.method': 'Quoted rate = total quote ÷ built-up area (or total = rate × area when you enter a rate). Benchmark total = your rate × area. Difference % = (quoted rate − your rate) ÷ your rate × 100. Breakdown coverage = entered costs ÷ quote × 100; each category\'s % = its amount ÷ quote × 100. Margin is shown only if you enter one.',
  'site.calculators.contractorQuote.disclaimer': 'This is an arithmetic check of the figures you entered against your own benchmark. It is not a valuation, a legal assessment or a judgement of the contractor; quotations differ in specification, materials and scope.',
