  'site.calculators.stampDuty.sourceTelangana': 'Telangana rates: stamp duty on sale 5.5% (G.O.Ms.No.59, Revenue (Registration) Department, 20-07-2021, in force from 22-07-2021); registration fee on sale deeds 0.5%, or 2% in a Gram Panchayat (Table of Fees under Section 78 of the Registration Act, in force from 02-09-2021). The orders set one rate regardless of buyer type or residential/commercial use.',
  'site.calculators.stampDuty.method': 'Stamp duty = rate × property value; registration fee = rate × property value; effective charge = total ÷ property value × 100. The charges here are applied to the value you enter, but the actual duty is assessed on the government guideline (market) value or the transaction value as the applicable rules require, so this is an estimate, not the final legal assessment. Amounts are rounded to the nearest rupee for display.',
